// PATCH: Keep agent output observable when --since takes precedence over --latest-only.
func TestEmitLatestOnlySinceWarning(t *testing.T) {
	t.Parallel()

	t.Run("json", func(t *testing.T) {
		var out bytes.Buffer
		emitLatestOnlySinceWarning(&out, false)

		var event struct {
			Event   string `json:"event"`
			Reason  string `json:"reason"`
			Message string `json:"message"`
		}
		if err := json.Unmarshal(out.Bytes(), &event); err != nil {
			t.Fatalf("warning is not valid JSON: %v", err)
		}
		if event.Event != "sync_warning" || event.Reason != "latest_only_ignored" {
			t.Fatalf("unexpected warning event: %+v", event)
		}
		if !strings.Contains(event.Message, "--since takes precedence") {
			t.Fatalf("warning does not explain precedence: %q", event.Message)
		}
	})

	t.Run("human", func(t *testing.T) {
		var out bytes.Buffer
		emitLatestOnlySinceWarning(&out, true)
		if got := out.String(); !strings.Contains(got, "warning: --latest-only ignored") {
			t.Fatalf("unexpected human warning: %q", got)
		}
	})
}
